const seed={version:1,draft:{'KSW-AA-VG-001-F1':'oud concept'},first:{'KSW-AA-VG-001-F1':'oud eerst'},last:{'KSW-AA-VG-001-F1':'oud laatst'}};
async function stored(page,id){return page.evaluate(id=>new Promise((resolve,reject)=>{const q=indexedDB.open('klink-writing-form-v1',1);q.onsuccess=()=>{const db=q.result,t=db.transaction('answers'),r=t.objectStore('answers').get(id);t.oncomplete=()=>{resolve(r.result);db.close();};t.onerror=()=>reject(t.error);};q.onerror=()=>reject(q.error);}),id);}
async function play(page,button,key){await page.evaluate(()=>{window.writingEnded=[];});await button.click();await page.waitForFunction(key=>window.writingEnded.some(e=>e.key===key&&e.native&&e.seconds>0),key);}
