  const page=await context.newPage();page.on('pageerror',e=>errors.push({engine,message:e.message}));await page.goto(base);await page.evaluate(seed=>new Promise((resolve,reject)=>{const q=indexedDB.open('klink-writing-form-v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('answers');q.onsuccess=()=>{const db=q.result,t=db.transaction('answers','readwrite');t.objectStore('answers').put(seed,'KSW-AA-VG-001');t.oncomplete=()=>{db.close();resolve();};t.onerror=()=>reject(t.error);};q.onerror=()=>reject(q.error);}),seed);
  const played=new Set();let instructed=false;
